# 推斷：資料表=用料明細（表頭第2列）｜欄位=本廠區狀態（H欄）｜篩選=狀態 != 'Ok'｜輸出=新工作表
import openpyxl

wb = openpyxl.load_workbook(INPUT_PATH)
ws = wb['用料明細']

# 建立區塊標題到欄位範圍的映射（第1列合併儲存格）
block_ranges = {}
for merged_range in ws.merged_cells.ranges:
    if merged_range.min_row == 1 and merged_range.max_row == 1:
        min_col = merged_range.min_col
        max_col = merged_range.max_col
        title = ws.cell(row=1, column=min_col).value
        if title:
            block_ranges[title] = (min_col, max_col)

# 建立有效欄名對照：(區塊標題, 第2列欄名) -> 欄索引
header_row = 2
field_map = {}
for col_idx in range(1, ws.max_column + 1):
    header_val = ws.cell(row=header_row, column=col_idx).value
    if header_val is None:
        continue
    block_title = None
    for title, (min_col, max_col) in block_ranges.items():
        if min_col <= col_idx <= max_col:
            block_title = title
            break
    if block_title:
        field_map[(block_title, header_val)] = col_idx

# 找到本廠狀態欄索引
target_col = field_map.get(('本廠', '狀態'))
if target_col is None:
    raise ValueError("找不到本廠狀態欄")

# 建立新工作表
if '本廠異常' in wb.sheetnames:
    del wb['本廠異常']
new_ws = wb.create_sheet('本廠異常')

# 複製表頭（第2列）
for col_idx in range(1, ws.max_column + 1):
    new_ws.cell(row=1, column=col_idx, value=ws.cell(row=header_row, column=col_idx).value)

# 篩選資料：本廠狀態不等於 'Ok' 的列
output_row = 2
for row_idx in range(3, ws.max_row + 1):
    status_val = ws.cell(row=row_idx, column=target_col).value
    if status_val != 'Ok':
        for col_idx in range(1, ws.max_column + 1):
            new_ws.cell(row=output_row, column=col_idx, value=ws.cell(row=row_idx, column=col_idx).value)
        output_row += 1

wb.save(OUTPUT_PATH)
```

```python
# 推斷：資料表=料表（表頭第1-2列）｜欄位=功能（E欄）｜主檔=料表｜鍵=無｜篩選=功能非良品｜輸出=新工作表
import openpyxl

wb = openpyxl.load_workbook(INPUT_PATH)
ws = wb['料表']

# 建立欄名到列索引的映射（第1列與第2列合併判斷）
col_map = {}
# 第1列：主要欄位
for cell in ws[1]:
    if cell.value is not None:
        col_map[cell.value] = cell.column
# 第2列：子欄位（覆蓋或新增，例如「功能」）
for cell in ws[2]:
    if cell.value is not None:
        col_map[cell.value] = cell.column

# 需要的欄位
required = ['項次', '料號', '品名', '功能']
for field in required:
    if field not in col_map:
        raise ValueError(f"找不到欄位: {field}")

# 取得各欄位的列索引（1-based）
col_idx = {field: col_map[field] for field in required}

# 建立新工作表（若已存在則先刪除）
if '功能非良品' in wb.sheetnames:
    del wb['功能非良品']
new_ws = wb.create_sheet('功能非良品')

# 寫入表頭
for i, field in enumerate(required, start=1):
    new_ws.cell(row=1, column=i, value=field)

# 從第3列開始篩選資料
row_out = 2
for row in ws.iter_rows(min_row=3, max_row=ws.max_row, values_only=False):
    # 取得功能欄位的值
    func_val = row[col_idx['功能'] - 1].value
    if func_val != '良品':
        # 寫入符合條件的列
        for j, field in enumerate(required, start=1):
            val = row[col_idx[field] - 1].value
            new_ws.cell(row=row_out, column=j, value=val)
        row_out += 1

wb.save(OUTPUT_PATH)
